"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { User } from "@/components/ui/icons";

// Avatar: generated by UIX from the design system. Same variants and sizes as the Figma component.

const avatarVariants = cva(
  "skin-keep relative inline-flex shrink-0 select-none items-center justify-center bg-brand-subtle [&_svg]:shrink-0",
  {
    variants: {
      size: {
        xs: "size-6 text-label-small [&_svg]:size-3",
        sm: "size-8 text-label-small [&_svg]:size-4",
        md: "size-10 text-label-medium [&_svg]:size-5",
        lg: "size-12 text-label-large [&_svg]:size-6",
        xl: "size-16 text-title-medium [&_svg]:size-8",
      },
      shape: {
        circle: "rounded-full",
        rounded: "",
      },
      type: {
        initials: "text-fg-brand",
        icon: "text-icon-brand",
      },
    },
    compoundVariants: [
      { shape: "rounded", size: "xs", class: "rounded-md" },
      { shape: "rounded", size: "sm", class: "rounded-md" },
      { shape: "rounded", size: "md", class: "rounded-md" },
      { shape: "rounded", size: "lg", class: "rounded-lg" },
      { shape: "rounded", size: "xl", class: "rounded-lg" },
    ],
    defaultVariants: {
      size: "md",
      shape: "circle",
      type: "initials",
    },
  },
);

export interface AvatarProps
  extends React.HTMLAttributes<HTMLSpanElement>,
    VariantProps<typeof avatarVariants> {
  /** Photo; initials or the icon show when it is missing. */
  src?: string;
  alt?: string;
  initials?: string;
  /** Online dot on the corner. */
  status?: boolean;
  /** Count pill on the corner. */
  badge?: React.ReactNode;
}

const Avatar = React.forwardRef<HTMLSpanElement, AvatarProps>(
  ({ className, size, shape, type, src, alt = "", initials, status = false, badge, children, ...props }, ref) => (
    <span data-slot="avatar" data-kind="chip" ref={ref} className={cn(avatarVariants({ size, shape, type }), className)} {...props}>
      {src ? (
        <img src={src} alt={alt} className="size-full rounded-[inherit] object-cover" />
      ) : (
        children ?? ((type ?? "initials") === "icon" ? <User aria-hidden /> : initials)
      )}
      {status ? <span aria-hidden className="absolute bottom-0 right-0 rounded-full ring-2 bg-success ring-surface size-[10px]" /> : null}
      {badge != null ? <span className="absolute -right-1 -top-1 inline-flex min-w-4 items-center justify-center rounded-full ring-2 bg-danger text-fg-on-danger ring-surface px-1 text-label-small">{badge}</span> : null}
    </span>
  ),
);
Avatar.displayName = "Avatar";

export { Avatar, avatarVariants };
